-- Council populations: ONS mid-year population estimates, mid-2025, for every council (owner's decision, 19 Oct 2026).
-- Source: ONS, Population estimates for the UK, England, Wales, Scotland and Northern Ireland: mid-2025, table MYE4
-- (mye25tablesuk.xlsx, published 1 October 2026). It includes National Records of Scotland's figures for Scottish council areas
-- and NISRA's for Northern Ireland; county councils have their own row.
-- Replaces values backfilled from Wikidata (scripts/backfill-council-wikidata.js, P1082), which are from various years
-- (mid-2011 to mid-2024) and in a few cases a different area (Kent 576,100; Preston 365,000). Barnsley and Sheffield had
-- none. Northern Ireland held NISRA mid-2024 (migration 2026-10-17b).
-- Adds population_year and population_source so the page can say "Population (mid-2025 estimate)" and name the source.
-- Each row is changed only if it still holds the value read on 19 Oct 2026; old values kept in councils_population_backup_20261019r.
\set ON_ERROR_STOP on
BEGIN;

ALTER TABLE public.councils ADD COLUMN population_year text, ADD COLUMN population_source text, ADD COLUMN population_source_url text CHECK (population_source_url ~ '^https://');
COMMENT ON COLUMN public.councils.population_year IS 'Year of the population estimate, e.g. mid-2025';
COMMENT ON COLUMN public.councils.population_source IS 'Publisher and title of the population estimate';

CREATE TEMP TABLE pop_new (gss text PRIMARY KEY, old_population integer, new_population integer NOT NULL CHECK (new_population > 0)) ON COMMIT DROP;

DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM pop_new;
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 rows listed, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils c JOIN pop_new p ON p.gss = c.gss_code AND c.population IS NOT DISTINCT FROM p.old_population;
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 councils still holding the value read on 19 Oct, found %', n; END IF;
  -- the councils that are not county councils cover the UK once: their total must be ONS's UK total for mid-2025
  SELECT sum(p.new_population) INTO n FROM pop_new p JOIN public.councils c ON c.gss_code = p.gss WHERE c.type <> 'county';
  IF n <> 69483939 THEN RAISE EXCEPTION 'councils total % is not the UK total 69483939', n; END IF;
END $$;

CREATE TABLE public.councils_population_backup_20261019r AS SELECT slug, gss_code, population FROM public.councils;
ALTER TABLE public.councils_population_backup_20261019r ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.councils_population_backup_20261019r FROM anon, authenticated;

UPDATE public.councils c SET population = p.new_population, population_year = 'mid-2025',
  population_source = 'ONS, mid-year population estimates (including NRS for Scotland and NISRA for Northern Ireland)',
  population_source_url = 'https://www.ons.gov.uk/peoplepopulationandcommunity/populationandmigration/populationestimates/datasets/populationestimatesforukenglandandwalesscotlandandnorthernireland'
  FROM pop_new p WHERE p.gss = c.gss_code AND c.population IS NOT DISTINCT FROM p.old_population;

DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM public.councils c JOIN pop_new p ON p.gss = c.gss_code AND c.population = p.new_population AND c.population_year = 'mid-2025';
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 councils on mid-2025, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils_population_backup_20261019r;
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 rows backed up, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE population IS NULL;
  IF n <> 0 THEN RAISE EXCEPTION '% councils with no population', n; END IF;
END $$;

SELECT c.slug, b.population AS old_population, c.population AS new_population FROM public.councils c JOIN public.councils_population_backup_20261019r b USING (slug)
  WHERE c.slug IN ('cardiff', 'kent', 'preston', 'city-of-london-corporation', 'glasgow', 'belfast', 'barnsley') ORDER BY 1;

COMMIT;
